<style>
.ad-page{color:#153d58}.ad-hero{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:14px;padding:22px 26px;border-radius:16px;color:#fff;background:linear-gradient(112deg,#0b4d78,#0789ad 68%,#17aaa5);box-shadow:0 12px 30px rgba(8,78,116,.16)}
.ad-hero__main{display:flex;align-items:center;gap:16px}.ad-hero__icon{display:grid;place-items:center;width:54px;height:54px;border:1px solid rgba(255,255,255,.38);border-radius:14px;background:rgba(255,255,255,.12);font-size:24px}.ad-hero h1{margin:0 0 4px;font-size:25px;font-weight:800}.ad-hero p{margin:0;opacity:.9}.ad-eyebrow{font-size:11px;font-weight:800;letter-spacing:.08em;opacity:.82}
.ad-card{margin-bottom:14px;border:1px solid #d4e3eb;border-radius:14px;background:#fff;box-shadow:0 7px 22px rgba(18,68,96,.07);overflow:hidden}.ad-card__head{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid #dce9ef;background:#f2f9fb}.ad-card__head h2{margin:0;font-size:17px;font-weight:800}.ad-card__body{padding:18px}
.ad-search{display:grid;grid-template-columns:minmax(220px,1fr) auto auto;gap:9px}.ad-search input{height:42px;border:1px solid #bfd6e2;border-radius:9px;padding:0 13px}.ad-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:40px;padding:9px 14px;border:1px solid #a9cad9;border-radius:9px;color:#075b7b!important;background:#fff;font-weight:700;text-decoration:none!important}.ad-btn--primary{border-color:#0b80a4;color:#fff!important;background:#0b80a4}.ad-btn--soft{background:#edf8fb}
.ad-table{width:100%;border-collapse:collapse}.ad-table th{padding:10px 12px;color:#577488;background:#f4f8fa;font-size:11px;text-transform:uppercase;letter-spacing:.04em}.ad-table td{padding:12px;border-top:1px solid #e1ebf0;vertical-align:middle}.ad-name{display:block;color:#0d4e70;font-weight:800}.ad-meta{display:block;margin-top:3px;color:#718899;font-size:12px}.ad-pill{display:inline-flex;align-items:center;padding:4px 9px;border-radius:999px;color:#05708c;background:#e3f6f7;font-size:11px;font-weight:800}
.ad-patient{display:grid;grid-template-columns:1.4fr repeat(3,minmax(120px,.7fr));gap:12px}.ad-patient__item{padding:12px 14px;border:1px solid #d6e5ec;border-radius:10px;background:#f9fcfd}.ad-patient__item small{display:block;margin-bottom:4px;color:#718899;font-size:10px;font-weight:800;text-transform:uppercase}.ad-patient__item strong{color:#113f5b}
.ad-doc-layout{display:grid;grid-template-columns:340px minmax(0,1fr);gap:14px}.ad-doc-list{display:flex;flex-direction:column;gap:8px}.ad-doc{display:grid;grid-template-columns:52px 1fr auto;align-items:center;gap:10px;padding:11px;border:1px solid #d6e5ec;border-radius:10px;background:#fff;cursor:pointer}.ad-doc:hover,.ad-doc.is-active{border-color:#0b8eaa;background:#ebf9fb}.ad-doc__code{display:grid;place-items:center;height:38px;border-radius:8px;color:#fff;background:#0b789e;font-size:12px;font-weight:900}.ad-doc strong{font-size:13px}.ad-doc small{display:block;color:#718899}.ad-viewer{min-height:700px;border:1px solid #cddde6;border-radius:12px;overflow:hidden;background:#374047}.ad-viewer iframe{display:block;width:100%;height:700px;border:0;background:#fff}.ad-empty{padding:34px;text-align:center;color:#718899}.ad-actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:12px}
@media(max-width:1000px){.ad-doc-layout{grid-template-columns:1fr}.ad-viewer,.ad-viewer iframe{min-height:560px;height:560px}}@media(max-width:760px){.ad-hero{align-items:flex-start}.ad-search{grid-template-columns:1fr}.ad-patient{grid-template-columns:1fr 1fr}.ad-table thead{display:none}.ad-table tr,.ad-table td{display:block}.ad-table tr{padding:8px;border-top:1px solid #e1ebf0}.ad-table td{padding:6px 10px;border:0}.ad-patient{grid-template-columns:1fr}}
</style>
